<div class="page-heading"><div><span class="eyebrow">CUSTOMER BILLING</span><h1>Invoices</h1><p>From a new draft to a recorded payment.</p></div><a class="button primary" href="<?= e(url('invoice')) ?>"><?= icon('plus') ?>Create invoice</a></div>
<div class="table-wrap"><table><thead><tr><th>Invoice</th><th>Customer</th><th>Issued</th><th>Due</th><th>Status</th><th class="number">Total</th><th></th></tr></thead><tbody><?php foreach($invoices as $i): ?><tr><td><a class="strong" href="<?= e(url('invoice',['id'=>$i['id']])) ?>"><?= e($i['number']) ?></a></td><td><?= e($i['customer_name']) ?></td><td class="nowrap"><?= short_date($i['issue_date']) ?></td><td class="nowrap <?= $i['status']==='sent'&&$i['due_date']<date('Y-m-d')?'negative':'' ?>"><?= short_date($i['due_date']) ?></td><td><?= badge($i['status']) ?></td><td class="number strong"><?= money($i['total']) ?></td><td><a class="icon-button" title="View invoice" aria-label="View <?= e($i['number']) ?>" href="<?= e(url('invoice',['id'=>$i['id']])) ?>"><?= icon('arrow-up-right') ?></a></td></tr><?php endforeach ?><?php if(!$invoices): ?><tr><td colspan="7"><div class="empty-state"><?= icon('file-text') ?><h3>Your next invoice starts here</h3><p>Add a customer in Contacts, then create your invoice.</p><a class="button" href="<?= e(url('contacts')) ?>"><?= icon('users') ?>Contacts</a></div></td></tr><?php endif ?></tbody></table></div>
